// The Huron documentation: a static Starlight site the web serves at /docs. `npm run build` syncs
// the guides from docs/*.md (scripts/sync.mjs) and builds into dist/; the CLI reference under
// src/content/docs/reference/cli/ is generated by scripts/cli_reference.py at the repository root.
import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import cliSidebar from './src/content/docs/reference/cli/_sidebar.json' with { type: 'json' };

export default defineConfig({
	base: '/docs',
	trailingSlash: 'always',
	output: 'static',
	// No typographic rewriting: smartypants would turn `--org` in prose into an en dash and curl the
	// quotes around values, so pasted options would not work in a shell.
	markdown: { smartypants: false },
	integrations: [
		starlight({
			title: 'Huron Docs',
			description: 'Using and running Huron: the CLI, the guides and the CLI reference.',
			// The dark mark has light tiles, so it stays visible on the dark header. The SiteTitle
			// override shows the mark of the active theme.
			logo: {
				light: './src/assets/huron-mark.svg',
				dark: './src/assets/huron-mark-dark.svg',
				alt: ''
			},
			favicon: '/favicon.svg',
			customCss: ['./src/styles/brand.css'],
			// A link back to the web (`/`) in the header: beside the theme selector on wide screens
			// (SocialIcons), as an icon beside the search button on narrow ones (Search).
			components: {
				SocialIcons: './src/components/SocialIcons.astro',
				Search: './src/components/Search.astro',
				SiteTitle: './src/components/SiteTitle.astro'
			},
			sidebar: [
				{ label: 'Getting started', items: ['getting-started'] },
				{ label: 'Guides', items: [{ autogenerate: { directory: 'guides' } }] },
				{ label: 'CLI reference', items: cliSidebar },
				{ label: 'Administration', items: [{ autogenerate: { directory: 'administration' } }] }
			]
		})
	]
});
